draw:
var Z = Math.round(p.Z);
var nsel = Math.round(p.n);
var NMAX = 4;
var cx = W * 0.42, cy = H * 0.5;
var Rmax = Math.min(W * 0.36, H * 0.42);
var scale = Rmax / (NMAX * NMAX);
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";
ctx.textBaseline = "middle";

// orbits
var i;
for (i = 1; i <= NMAX; i++) {
  var R = i * i * scale;
  ctx.beginPath();
  ctx.arc(cx, cy, R, 0, Math.PI * 2);
  if (i === nsel) {
    ctx.strokeStyle = C.accent;
    ctx.lineWidth = 2;
    ctx.setLineDash([]);
  } else {
    ctx.strokeStyle = C.faint;
    ctx.lineWidth = 1;
    ctx.setLineDash([3, 4]);
  }
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = (i === nsel) ? C.accent : C.faint;
  ctx.fillText("n=" + i, cx + 3, cy - R - 8);
}
ctx.lineWidth = 1;

// nucleus
ctx.fillStyle = C.ink;
ctx.beginPath();
ctx.arc(cx, cy, 5, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("nucleus +" + Z + "e", cx + 9, cy + 12);

// electron: period goes as n^3 / Z^2
var period = 1.1 * nsel * nsel * nsel / (Z * Z);
var ang = 2 * Math.PI * (t / period);
var Rn = nsel * nsel * scale;
var ex = cx + Rn * Math.cos(ang);
var ey = cy - Rn * Math.sin(ang);

// radius line
ctx.strokeStyle = C.rule;
ctx.setLineDash([2, 3]);
ctx.beginPath();
ctx.moveTo(cx, cy);
ctx.lineTo(ex, ey);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.rule;
ctx.fillText("r", (cx + ex) / 2 + 5, (cy + ey) / 2 - 5);

// velocity arrow, tangent
var vx = -Math.sin(ang), vy = -Math.cos(ang);
var alen = 26;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(ex, ey);
ctx.lineTo(ex + vx * alen, ey + vy * alen);
ctx.stroke();
var hx = ex + vx * alen, hy = ey + vy * alen;
ctx.beginPath();
ctx.moveTo(hx, hy);
ctx.lineTo(hx - vx * 6 - vy * 4, hy - vy * 6 + vx * 4);
ctx.lineTo(hx - vx * 6 + vy * 4, hy - vy * 6 - vx * 4);
ctx.closePath();
ctx.fillStyle = C.figure;
ctx.fill();
ctx.lineWidth = 1;
ctx.fillStyle = C.figure;
ctx.fillText("v", hx + 6, hy - 2);

ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(ex, ey, 4.5, 0, Math.PI * 2);
ctx.fill();

// side panel numbers
var r_nm = 0.0529 * nsel * nsel / Z;
var v_ms = 2.19e6 * Z / nsel;
var E_eV = -13.6 * Z * Z / (nsel * nsel);
var px = W - 6;
ctx.textAlign = "right";
ctx.fillStyle = C.ink;
ctx.fillText("r = " + r_nm.toFixed(4) + " nm", px, 18);
ctx.fillStyle = C.figure;
ctx.fillText("v = " + (v_ms / 1e6).toFixed(3) + "e6 m/s", px, 36);
ctx.fillStyle = C.ink;
ctx.fillText("E = " + E_eV.toFixed(2) + " eV", px, 54);
ctx.fillStyle = C.rule;
ctx.fillText("L = " + nsel + " hbar", px, 72);
ctx.textAlign = "left";

out.note = "n = " + nsel + ", Z = " + Z + ": r = " + r_nm.toFixed(4) + " nm, v = " + v_ms.toExponential(2) + " m/s, one orbit every " + (2 * Math.PI * (0.0529e-9 * nsel * nsel / Z) / v_ms).toExponential(2) + " s";

var Z = Math.round(p.Z);
var ni = Math.round(p.ni);
var nf = Math.round(p.nf);
if (nf >= ni) { nf = ni - 1; }
if (nf < 1) { nf = 1; }
var R = 13.6 * Z * Z;
var NMAX = 10;
var padT = 20, padB = 22;
var Emin = -R;
function Y(e) { return H - padB - (e - Emin) / (0 - Emin) * (H - padT - padB); }
var xL = 46, xR = W * 0.60;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";

// zero line
ctx.textAlign = "right";
ctx.strokeStyle = C.rule;
ctx.setLineDash([2, 4]);
ctx.beginPath();
ctx.moveTo(xL, Y(0));
ctx.lineTo(W - 8, Y(0));
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.rule;
ctx.fillText("E = 0  (ionised)", W - 10, Y(0) - 10);

// levels
var n;
for (n = 1; n <= NMAX; n++) {
  var E = -R / (n * n);
  var y = Y(E);
  var hit = (n === ni || n === nf);
  ctx.strokeStyle = hit ? C.accent : C.faint;
  ctx.lineWidth = hit ? 2 : 1;
  ctx.beginPath();
  ctx.moveTo(xL, y);
  ctx.lineTo(xR, y);
  ctx.stroke();
  if (n <= 5 || hit) {
    ctx.fillStyle = hit ? C.accent : C.faint;
    ctx.textAlign = "right";
    ctx.fillText("n=" + n, xL - 5, y);
    ctx.textAlign = "left";
    ctx.fillStyle = hit ? C.accent : C.faint;
    ctx.fillText(E.toFixed(2) + " eV", xR + 6, y);
  }
}
ctx.lineWidth = 1;

// transition arrow
var yi = Y(-R / (ni * ni)), yf = Y(-R / (nf * nf));
var ax = xL + (xR - xL) * 0.35;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(ax, yi);
ctx.lineTo(ax, yf);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(ax, yf);
ctx.lineTo(ax - 4, yf - 8);
ctx.lineTo(ax + 4, yf - 8);
ctx.closePath();
ctx.fillStyle = C.figure;
ctx.fill();
ctx.lineWidth = 1;

var dE = R * (1 / (nf * nf) - 1 / (ni * ni));
var lam = 1240 / dE;

// emitted photon, a wave travelling right
var span = W - (xR + 70);
if (span < 40) { span = 40; }
var x0 = xR + 62;
var travel = (t % 2.2) / 2.2;
var yph = (yi + yf) / 2;
ctx.strokeStyle = C.figure;
ctx.beginPath();
var s;
var lead = x0 + travel * span;
for (s = 0; s <= 46; s += 1) {
  var xx = lead - 46 + s;
  if (xx < x0) { continue; }
  var yy = yph + 6 * Math.sin(s * 0.7);
  if (xx === lead - 46 + s && s === 0) { ctx.moveTo(xx, yy); } else { ctx.lineTo(xx, yy); }
}
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.textAlign = "left";
ctx.fillText("photon", x0, yph + 20);

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("n=" + ni + " to n=" + nf, (xL + xR) / 2, padT - 8 + 6);

out.note = "Z = " + Z + ", n = " + ni + " to " + nf + ":  dE = " + dE.toFixed(3) + " eV,  lambda = 1240/dE = " + (lam < 10000 ? lam.toFixed(1) + " nm" : lam.toExponential(2) + " nm");

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";
ctx.textAlign = "center";
var padL = 34, padR = 18, padT = 26, padB = 34;
var lmin = 90, lmax = 2400;
function X(lam) {
  return padL + (Math.log(lam) - Math.log(lmin)) / (Math.log(lmax) - Math.log(lmin)) * (W - padL - padR);
}
var axisY = H - padB;

// axis
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(padL, axisY);
ctx.lineTo(W - padR, axisY);
ctx.stroke();
var ticks = [100, 200, 400, 800, 1600];
var i;
for (i = 0; i < ticks.length; i++) {
  var xt = X(ticks[i]);
  ctx.strokeStyle = C.rule;
  ctx.beginPath();
  ctx.moveTo(xt, axisY);
  ctx.lineTo(xt, axisY + 4);
  ctx.stroke();
  ctx.fillStyle = C.rule;
  ctx.fillText(String(ticks[i]), xt, axisY + 14);
}
ctx.fillStyle = C.ink;
ctx.fillText("wavelength (nm, log scale)", W / 2, H - 6);

// visible band
ctx.fillStyle = C.faint;
ctx.globalAlpha = 0.35;
ctx.fillRect(X(400), padT, X(700) - X(400), axisY - padT);
ctx.globalAlpha = 1;
ctx.fillStyle = C.faint;
ctx.fillText("visible", (X(400) + X(700)) / 2, padT - 12);

var names = ["Lyman", "Balmer", "Paschen"];
var rowH = (axisY - padT) / 3;
var f;
for (f = 1; f <= 3; f++) {
  var yTop = padT + (f - 1) * rowH + 6;
  var yBot = yTop + rowH - 16;
  var col = (f === 2) ? C.accent : C.figure;
  var n2;
  for (n2 = f + 1; n2 <= 14; n2++) {
    var dE = 13.6 * (1 / (f * f) - 1 / (n2 * n2));
    var lam = 1240 / dE;
    var x = X(lam);
    ctx.strokeStyle = col;
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(x, yTop);
    ctx.lineTo(x, yBot);
    ctx.stroke();
  }
  // series limit
  var lamLim = 1240 / (13.6 / (f * f));
  ctx.strokeStyle = C.ink;
  ctx.setLineDash([2, 3]);
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(X(lamLim), yTop - 4);
  ctx.lineTo(X(lamLim), yBot + 4);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.ink;
  ctx.textAlign = "left";
  ctx.fillText(names[f - 1] + " (ends on n=" + f + ")", padL + 4, yTop - 2);
  ctx.textAlign = "center";
  ctx.fillStyle = C.rule;
  ctx.fillText("limit " + lamLim.toFixed(0), X(lamLim) + 30, yBot + 2);
}
ctx.lineWidth = 1;
